/// 职业神器 —— 领域模型与数据（与 UI 原型 `SECT_ARTIFACTS` 一致）。
///
/// 十三大门派各有专属武器体系，按 42 / 52 / 62 / 72 / 82 / 86 / 92 / 96 / 102
/// 级九档；每档含名称、简介、基础属性（stats）、神兵特性（extra）与获取途径（how）。
/// 昆仑（2026-10-23 上线）九档数据官方尚未公布，暂缺条目（页面显示占位）。
library;

import 'package:flutter/foundation.dart';

/// 一档神器（42 / 52 / 62 / 72 / 82 / 86 / 92 / 96 / 102）。
@immutable
class JobArtifactTier {
  const JobArtifactTier({
    required this.lv,
    required this.name,
    required this.intro,
    required this.stats,
    required this.extra,
    required this.how,
  });

  final int lv;
  final String name;

  /// 神器简介。
  final String intro;

  /// 基础属性（原型为 `'名称 +数值'` 文案，如 `'攻击 +380'`）。
  final List<String> stats;

  /// 神兵特性（共鸣效果）。
  final String extra;

  /// 获取途径步骤。
  final List<String> how;
}

/// 一门派的武器体系。
@immutable
class JobArtifact {
  const JobArtifact({required this.weapon, required this.tiers});

  /// 适配武器类型（如 枪棒/刀斧 / 单短/双短）。
  final String weapon;

  /// 九档神器。
  final List<JobArtifactTier> tiers;
}

